ALTER TABLE properties ADD COLUMN garage_slots INT NOT NULL DEFAULT 0;
ALTER TABLE properties ADD COLUMN tax_amount BIGINT NOT NULL DEFAULT 0;
ALTER TABLE properties ADD COLUMN tax_due_at DATETIME NULL;
ALTER TABLE character_vehicles ADD COLUMN mileage DOUBLE NOT NULL DEFAULT 0;
ALTER TABLE character_vehicles ADD COLUMN oil DOUBLE NOT NULL DEFAULT 100;
ALTER TABLE character_vehicles ADD COLUMN battery DOUBLE NOT NULL DEFAULT 100;
ALTER TABLE character_vehicles ADD COLUMN insurance_until DATETIME NULL;
ALTER TABLE character_vehicles ADD COLUMN vin VARCHAR(32) NULL UNIQUE;
CREATE TABLE IF NOT EXISTS family_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,family_id BIGINT UNSIGNED NOT NULL,character_id BIGINT UNSIGNED NULL,action VARCHAR(64) NOT NULL,details_json JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(family_id,created_at),FOREIGN KEY(family_id) REFERENCES families(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS vehicle_keys(vehicle_id BIGINT UNSIGNED NOT NULL,character_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(vehicle_id,character_id),FOREIGN KEY(vehicle_id) REFERENCES character_vehicles(id) ON DELETE CASCADE,FOREIGN KEY(character_id) REFERENCES characters(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS property_keys(property_id BIGINT UNSIGNED NOT NULL,character_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(property_id,character_id),FOREIGN KEY(property_id) REFERENCES properties(id) ON DELETE CASCADE,FOREIGN KEY(character_id) REFERENCES characters(id) ON DELETE CASCADE);
